   5. ヘッダー
   ========================================================== */

.site-header {
  display: flex;
  justify-content: space-between;  /* ロゴを左端、ナビを右端へ */
  align-items: center;             /* 高さを中央で揃える */
  flex-wrap: wrap;
  gap: 12px 24px;
  padding-block: 20px;
  border-bottom: 1px solid var(--color-border);
}

